{
  "title": "星际信号",
  "scene": "你是一名太空船驾驶员，独自执行跨越银河的任务。突然，飞船发出警报，氧气供应系统出现故障。你必须尽快找到解决方案，否则剩余的氧气只够维持30分钟。此时，雷达上出现了一个未知的信号源，它似乎是一座废弃的太空站。在你的控制台上，还有一个未使用的应急修复工具包，但你不确定它是否能解决当前的故障。",
  "goal": "修复氧气供应系统或寻找替代方案",
  "clue": "场景中提到应急修复工具包和未知信号源",
  "choices": [
    {
      "id": "A",
      "text": "使用应急修复工具包尝试修复",
      "outcome": "你迅速拿起应急修复工具包，按照说明书上的步骤操作，奇迹般地修复了氧气供应系统。警报解除，你松了一口气，继续你的星际旅程。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "尝试联系未知信号源",
      "outcome": "你发送了一条求助信息给未知信号源，不久后收到了回复。对方是一群友好的太空探险者，他们提供了远程指导，帮助你修复了氧气供应系统。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "等待救援",
      "outcome": "你决定等待救援，但时间一分一秒过去，氧气逐渐耗尽。幸运的是，救援船在最后一刻到达，你被安全救出，但任务因此被延误。",
      "result": "partial",
      "next": "retry"
    }
  ]
}
